function spawnBonusPattern(){if(model.bonusCoinsSpawned>=32){model.bonusPatternIn=99;return;}const pattern=Math.floor(model.bonusCoinsSpawned/8)%4,baseY=160+(pattern%3)*76;for(let i=0;i<8&&model.bonusCoinsSpawned<32;i++,model.bonusCoinsSpawned++){const x=1010+i*46,y=pattern===0?baseY+Math.sin(i*.9)*55:pattern===1?270+(i-3.5)*(i-3.5)*7:pattern===2?270+Math.sin(i*1.55)*92:150+(i%2)*210;model.objects.push({kind:"spore",x,y,w:30,h:30,phase:i*.45,done:true,hit:false});}model.bonusPatternIn=1.75;}
